/* ── CLI Terminal Showcase ──────────────────── */
.cli-terminal {
  background: #0a0a0a;
  border-radius: 10px;
  overflow: hidden;
  font-family: var(--font-mono);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.5), 0 0 0 1px #1f1f1f;
  max-width: 640px;
}

.cli-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 14px;
  background: #161616;
  border-bottom: 1px solid #1f1f1f;
}

.cli-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: block;
  flex-shrink: 0;
}

.cli-bar-title {
  margin-left: 8px;
  font-size: 0.6875rem;
  color: #555;
  flex: 1;
  text-align: center;
}

.cli-body {
  padding: 14px 18px 16px;
}

.cli-shell-line {
  font-size: 0.75rem;
  color: #555;
  margin-bottom: 14px;
}

.cli-shell-user { color: #888; }
.cli-shell-sep  { color: #666; }
.cli-shell-cmd  { color: #aaa; }

.cli-welcome {
  color: #888;
  font-size: 0.6875rem;
  margin: 0 0 10px;
}

.cli-logo-row {
  display: flex;
  align-items: flex-start;
  gap: 18px;
}

.cli-logo-col {
  flex: 1;
  min-width: 0;
  overflow: hidden;
}

.cli-logo {
  color: #e3120b;
  font-size: 8px;
  line-height: 1.3;
  margin: 0;
  padding: 0;
  background: none;
  border-radius: 0;
  white-space: pre;
  overflow: hidden;
}

.cli-version-tag {
  color: #444;
  font-size: 0.5625rem;
  text-align: center;
  margin-top: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.cli-status-bar {
  display: flex;
  justify-content: space-between;
  font-size: 0.625rem;
  color: #444;
  margin-top: 14px;
  padding-top: 8px;
  border-top: 1px solid #1a1a1a;
}

.cli-status-model { color: #777; }

.cli-prompt-row {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.6875rem;
  margin-top: 8px;
}

.cli-prompt-caret { color: #555; }

.cli-cursor {
  color: #e3120b;
  animation: cli-blink 1.2s step-end infinite;
  font-size: 0.625rem;
}

.cli-prompt-hint { color: #555; }

.cli-hint-row {
  font-size: 0.5625rem;
  color: #3a3a3a;
  margin-top: 5px;
}

.cli-hint-row kbd {
  font-family: var(--font-mono);
  font-size: 0.5625rem;
  color: #666;
  background: none;
  border: none;
  padding: 0;
}

@keyframes cli-blink {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0; }
}

