    border-radius: 10px;
  }

  .ide-install-btn {
    width: 100%;
    justify-content: center;
    border-right: none;
    border-bottom: 1px solid var(--border);
    padding: 0.75rem 1rem;
  }

  .ide-install-btn:last-child {
    border-bottom: none;
  }

  .why-stats {
    grid-template-columns: 1fr;
  }

  .main-content {
    padding: 0.875rem;
  }

  .article {
    max-width: 100%;
  }

  .article header {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
  }

  .article section {
    margin-top: 1.75rem;
  }

  .feature-grid,
  .tool-grid {
    grid-template-columns: 1fr;
