    overflow-x: auto;
  }

  /* Nav link sizing */
  .nav-link {
    padding: 0.5rem 1rem;
    font-size: 0.8125rem;
  }

  .nav-section-label {
    padding: 0.625rem 1rem 0.375rem;
  }

  /* Dictionary on small screens */
  .dict-letter-link {
    width: 1.75rem;
    height: 1.75rem;
    font-size: 0.6875rem;
  }

  .dict-term {
    padding: 0.75rem 1rem;
  }

  /* How-to steps */
  .how-to-step {
    gap: 0.625rem;
    font-size: 0.8125rem;
  }

  .how-to-num {
    width: 1.25rem;
    height: 1.25rem;
    font-size: 0.625rem;
  }

  /* Footer */
  .footer {
    margin-top: 2.5rem;
    padding-top: 1.25rem;
  }

  .footer-nav {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem 1rem;
  }

  /* Wiki */
  .wiki-term {
    padding: 0.75rem 1rem;
  }

  .wiki-filters {
    margin-bottom: 1rem;
  }

  .wiki-filter-row {
    gap: 0.25rem;
  }

  .source-pill,
  .category-pill {
    font-size: 0.625rem;
    padding: 0.2rem 0.5rem;
  }

  /* Demo mockup small phones */
  .demo-mockup-wrapper { margin: 1.5rem auto 0; }
  .demo-body { flex-direction: column; min-height: auto; }
  .demo-sidebar { width: 100%; border-right: none; border-bottom: 1px solid var(--grey-200); padding: 8px; }
  .demo-chat-panel { width: 100%; border-left: none; border-top: 1px solid var(--grey-200); }
  .demo-code { font-size: 7.5px; line-height: 1.6; }
  .demo-code-line { gap: 6px; padding: 0 6px; }
  .demo-legend { gap: 0.75rem; }
  .demo-legend-item { font-size: 10px; }

  /* ── Learn page small phones ── */
  .learn-lesson-num {
    width: 1.5rem;
    height: 1.5rem;
    font-size: 0.6875rem;
  }

  .learn-lesson-title {
    font-size: 0.9375rem;
  }

  .learn-lesson-sub {
    font-size: 0.6875rem;
  }

  .learn-lesson-desc {
    font-size: 0.75rem;
    line-height: 1.6;
  }

  .learn-window-segments {
    height: 36px;
  }

  .learn-segment-label {
    font-size: 0.375rem;
  }

  .learn-code-pre {
    font-size: 0.5625rem;
  }

  .learn-compact-visual {
    gap: 0.5rem;
    padding: 10px;
  }

  .learn-compact-col {
    max-width: 80px;
  }

  .learn-compact-bar {
    border-radius: 4px;
  }

  .learn-compact-val {
    font-size: 0.4375rem;
  }

  .learn-compact-detail {
    font-size: 0.5625rem;
  }

  .learn-compact-label {
    font-size: 0.5625rem;
  }

  .learn-compact-arrow svg {
    width: 24px;
    height: 24px;
  }
}

/* Extra small phones (iPhone SE, Galaxy S, etc.) */
